.article-art-4::after {
  content: ""; position: absolute; inset: 26% 30% 18% 30%;
  background: linear-gradient(180deg, #7eccaa, #2c6f55);
  border-radius: 30% 30% 8px 8px;
}

.article-body {
  padding: 20px 20px 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.article-feature .article-body { padding: 28px; gap: 12px; }
.article-feature h3 {
  font-family: "Fraunces", Georgia, serif;
  font-size: 1.7rem;
  line-height: 1.2;
  font-weight: 500;
}
.article-card h3 a:hover { color: var(--accent); }
.article-meta { color: var(--text-dim); font-size: 0.85rem; margin: 0; }
.tag {
