.article-body p:not(.article-meta):not(.byline) { color: var(--text-muted); margin: 0; }

/* Newsletter */
.newsletter {
  border-top: 1px solid var(--line);
  background:
    radial-gradient(50% 80% at 80% 100%, rgba(212,180,131,0.10), transparent 60%),
