}
.news-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.news-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: center;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 20px;
}
.news-form input[type="email"] {
  background: var(--bg-1);
  border: 1px solid var(--line);
  color: var(--text);
  padding: 14px 16px;
  border-radius: 10px;
  font-size: 1rem;
  width: 100%;
  transition: border-color .15s ease;
}
.news-form input[type="email"]::placeholder { color: var(--text-dim); }
.news-form input[type="email"]:focus-visible {
  border-color: var(--accent);
  outline: 2px solid rgba(212,180,131,0.35);
  outline-offset: 2px;
}
.news-form input[aria-invalid="true"] {
  border-color: var(--danger);
}
.news-form .btn { padding: 14px 22px; }
.news-help, .news-status {
  grid-column: 1 / -1;
  margin: 4px 4px 0;
  font-size: 0.82rem;
  color: var(--text-dim);
}
.news-status { min-height: 1.2em; color: var(--ok); }
.news-status.is-error { color: var(--danger); }

/* Footer */
.site-footer {
  background: var(--bg-1);
  border-top: 1px solid var(--line);
  padding: 64px 0 24px;
  margin-top: 32px;
}
.footer-inner {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 40px;
  border-bottom: 1px solid var(--line);
}
.footer-brand p { color: var(--text-muted); max-width: 36ch; margin: 14px 0 0; }
.site-footer h2 {
  font-family: inherit;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-weight: 600;
  color: var(--text-dim);
  margin: 0 0 14px;
}
.site-footer nav ul {
  list-style: none;
  padding: 0; margin: 0;
  display: grid; gap: 10px;
}
.site-footer nav a { color: var(--text-muted); transition: color .15s ease; }
.site-footer nav a:hover { color: var(--text); }
.footer-bottom {
  padding-top: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  color: var(--text-dim);
  font-size: 0.85rem;
}
.legal { list-style: none; padding: 0; margin: 0; display: flex; gap: 18px; }
.legal a:hover { color: var(--text); }

/* Toast */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--bg-3);
  color: var(--text);
  border: 1px solid var(--line-strong);
  padding: 12px 18px;
  border-radius: 999px;
  box-shadow: var(--shadow-2);
  font-size: 0.92rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s ease, transform .25s ease;
  z-index: 80;
}
.toast.is-visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.001ms !important;
    animation-duration: 0.001ms !important;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .chip, .icon-btn, .news-form input { border: 1px solid CanvasText; }
  .btn-primary { background: Highlight; color: HighlightText; }
  :focus-visible { outline: 2px solid Highlight; }
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-column: span 2; grid-row: auto; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .article-feature { grid-column: span 2; grid-row: auto; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .header-inner { gap: 12px; }
  .primary-nav { display: none; }
  .hero { padding: 40px 0 56px; }
  .hero-inner { grid-template-columns: 1fr; gap: 32px; }
  .hero-art { max-width: 360px; margin: 0 auto; }
  .hero-meta { grid-template-columns: 1fr 1fr; }
  .section { padding: 64px 0; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .article-feature { grid-column: auto; }
  .news-inner { grid-template-columns: 1fr; gap: 24px; }
  .news-form { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr 1fr; gap: 28px; }
}
@media (max-width: 380px) {
  .hero-meta { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
}
