/* Tokens */
:root {
  --bg: #0a0b0f;
  --bg-1: #0f1117;
  --bg-2: #151823;
  --bg-3: #1c2030;
  --line: #262a3a;
  --line-strong: #353a52;
  --text: #eef0f6;
  --text-muted: #a8aec1;
  --text-dim: #7a8099;
  --accent: #d4b483;        /* warm sand */
  --accent-strong: #e9c89a;
  --accent-ink: #1a1408;
  --danger: #ff6b6b;
  --ok: #5dd6a8;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-1: 0 1px 0 rgba(255,255,255,0.04) inset, 0 12px 30px rgba(0,0,0,0.4);
  --shadow-2: 0 24px 60px rgba(0,0,0,0.55);
  --container: 1200px;
  --header-h: 68px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font: inherit; color: inherit; cursor: pointer; }

/* Focus */
:focus { outline: none; }
:focus-visible {
  outline: 2px solid var(--accent-strong);
  outline-offset: 3px;
  border-radius: 4px;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 12px; top: -40px;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  z-index: 100;
  transition: top 0.15s ease;
}
.skip-link:focus { top: 12px; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10,11,15,0.78);
  backdrop-filter: saturate(180%) blur(14px);
  -webkit-backdrop-filter: saturate(180%) blur(14px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  height: var(--header-h);
  display: flex;
  align-items: center;
  gap: 24px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
}
.brand-mark { color: var(--accent); }
.brand-name {
  font-family: "Fraunces", "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  font-size: 1.25rem;
  letter-spacing: 0.01em;
}

.primary-nav { flex: 1; }
.primary-nav ul {
  list-style: none;
  display: flex;
  gap: 4px;
  margin: 0; padding: 0;
  justify-content: center;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--text-muted);
  font-size: 0.92rem;
  font-weight: 500;
  transition: color .15s ease, background .15s ease;
}
.primary-nav a:hover { color: var(--text); background: var(--bg-2); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 10px;
  color: var(--text-muted);
  transition: color .15s ease, background .15s ease, border-color .15s ease;
}
.icon-btn:hover { color: var(--text); background: var(--bg-2); border-color: var(--line); }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 5px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 11px;
  font-weight: 700;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transform: scale(0);
  transition: transform .2s cubic-bezier(.2,1.6,.4,1);
}
.cart-count.is-visible { transform: scale(1); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  border: 1px solid transparent;
  text-align: center;
  transition: transform .12s ease, background .15s ease, border-color .15s ease, color .15s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-strong); }
.btn-ghost {
  background: transparent;
  color: var(--text);
  border-color: var(--line-strong);
}
.btn-ghost:hover { background: var(--bg-2); border-color: var(--text-dim); }

/* Eyebrow / typography */
.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-dim);
  margin: 0 0 12px;
}
.eyebrow-accent { color: var(--accent); }

h1, h2, h3 {
  font-family: "Fraunces", "Cormorant Garamond", Georgia, serif;
  font-weight: 500;
  letter-spacing: -0.01em;
  margin: 0;
  color: var(--text);
}
h1 { font-size: clamp(2.4rem, 5vw, 3.8rem); line-height: 1.05; }
h2 { font-size: clamp(1.7rem, 3vw, 2.4rem); line-height: 1.15; }
h3 { font-size: 1.1rem; line-height: 1.3; font-weight: 600; }

/* Hero */
.hero {
  position: relative;
  padding: 64px 0 80px;
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  inset: -10% -10% auto -10%;
  height: 80%;
  background:
    radial-gradient(60% 50% at 75% 30%, rgba(212,180,131,0.18), transparent 60%),
    radial-gradient(40% 40% at 15% 70%, rgba(110,140,255,0.12), transparent 60%);
  pointer-events: none;
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 56px;
  align-items: center;
}
.hero-copy { max-width: 560px; }
.hero-lede {
  color: var(--text-muted);
  font-size: 1.1rem;
  margin: 18px 0 28px;
  max-width: 48ch;
}
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; }
.hero-meta {
  margin: 36px 0 0;
  padding: 18px 0 0;
  border-top: 1px solid var(--line);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.hero-meta div { padding-right: 12px; }
.hero-meta dt {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--text-dim);
  margin-bottom: 4px;
}
.hero-meta dd {
  margin: 0;
  color: var(--text);
  font-weight: 500;
}

.hero-art {
  position: relative;
  aspect-ratio: 1 / 1;
  max-width: 520px;
  margin-left: auto;
}
.hero-card {
  position: absolute;
  border-radius: 18px;
  border: 1px solid var(--line);
  box-shadow: var(--shadow-2);
  background-size: cover;
  background-position: center;
}
.hero-card-1 {
  inset: 0 28% 28% 0;
  background:
    linear-gradient(160deg, rgba(212,180,131,0.25), transparent 60%),
    radial-gradient(120% 80% at 30% 30%, #2a2f44, #11141d 70%);
}
.hero-card-1::after {
  content: "";
  position: absolute; inset: 22% 18%;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #4a5174, #1a1d2b 70%);
  box-shadow: inset 0 0 40px rgba(0,0,0,0.6), 0 30px 60px rgba(0,0,0,0.5);
}
.hero-card-2 {
  inset: 22% 0 0 38%;
  background:
    linear-gradient(180deg, #3a2f22, #1a140a);
}
.hero-card-2::after {
  content: "";
  position: absolute; inset: 30% 22% 22% 22%;
  border-radius: 40% 40% 8px 8px;
  background: linear-gradient(180deg, #d4b483, #8a6e44);
  box-shadow: inset 0 -10px 20px rgba(0,0,0,0.4);
}
.hero-card-3 {
  inset: 56% 28% 0 22%;
  background:
    linear-gradient(160deg, #1a2438, #0d1320);
}
.hero-card-3::after {
  content: "";
  position: absolute; inset: 25% 30% 25% 30%;
  border-radius: 4px;
  background: linear-gradient(180deg, #cfd6e8 0%, #cfd6e8 60%, #6f7a99 60%, #6f7a99 100%);
  box-shadow: 0 10px 20px rgba(0,0,0,0.4);
}
.hero-glow {
  position: absolute;
  inset: -20%;
  background: radial-gradient(closest-side, rgba(212,180,131,0.18), transparent 70%);
  filter: blur(40px);
  z-index: -1;
}

/* Strip */
.strip {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: var(--bg-1);
}
.strip-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 22px 24px;
  flex-wrap: wrap;
}
.strip-inner > span {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--text-dim);
}
.strip-inner ul {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 32px;
  flex: 1;
}
.strip-inner li {
  font-family: "Fraunces", Georgia, serif;
  color: var(--text-muted);
  font-size: 1rem;
  letter-spacing: 0.04em;
  opacity: 0.85;
}

/* Sections */
.section {
  padding: 88px 0;
}
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}
.section-sub {
  color: var(--text-muted);
  margin: 10px 0 0;
  max-width: 56ch;
}
.link-arrow {
  color: var(--text);
  font-weight: 600;
  font-size: 0.95rem;
  border-bottom: 1px solid var(--line-strong);
  padding-bottom: 4px;
  transition: color .15s ease, border-color .15s ease;
}
.link-arrow:hover { color: var(--accent); border-color: var(--accent); }

/* Filters */
.filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}
.chip {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid var(--line);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 500;
  transition: all .15s ease;
}
.chip:hover { color: var(--text); border-color: var(--line-strong); }
.chip.is-active {
  background: var(--text);
  color: var(--bg);
  border-color: var(--text);
}

/* Product grid */
.product-grid {
  list-style: none;
  margin: 0; padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product-card {
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .2s ease, border-color .2s ease, box-shadow .2s ease;
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  transform: translateY(-3px);
  border-color: var(--line-strong);
  box-shadow: var(--shadow-1);
}
.product-art {
  position: relative;
  aspect-ratio: 4 / 5;
  background: var(--bg-2);
  overflow: hidden;
}
.product-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 70% 20%, rgba(255,255,255,0.06), transparent 50%);
  pointer-events: none;
}
.product-tag {
  position: absolute;
  top: 12px; left: 12px;
  background: rgba(10,11,15,0.7);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  color: var(--text);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
  border: 1px solid var(--line);
}
.product-tag.tag-new { color: var(--ok); border-color: rgba(93,214,168,0.4); }
.product-tag.tag-sale { color: var(--accent); border-color: rgba(212,180,131,0.4); }

.product-body {
  padding: 16px 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--text-dim);
}
.product-name {
  font-family: "Fraunces", Georgia, serif;
  font-size: 1.05rem;
  font-weight: 500;
  color: var(--text);
}
.product-name a {
  background-image: linear-gradient(currentColor, currentColor);
  background-size: 0 1px;
  background-repeat: no-repeat;
  background-position: 0 100%;
  transition: background-size .25s ease;
}
.product-card:hover .product-name a { background-size: 100% 1px; }

.product-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 8px;
}
.price { margin: 0; font-weight: 600; font-size: 1rem; }
.price-now { color: var(--text); }
.price-was { color: var(--text-dim); font-weight: 400; margin-left: 6px; font-size: 0.9rem; }

.add-mini {
  background: var(--bg-3);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 999px;
  width: 34px; height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background .15s ease, color .15s ease, border-color .15s ease;
}
.add-mini:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }

/* Decorative product art (varied gradients/shapes) */
.art-1 { background: radial-gradient(120% 80% at 30% 30%, #2a2f44, #11141d 70%); }
.art-1::before {
  content: ""; position: absolute; inset: 28% 22% 22% 22%;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 30%, #5a6188, #1a1d2b 75%);
  box-shadow: inset 0 0 40px rgba(0,0,0,0.5);
}
.art-2 { background: linear-gradient(180deg, #2c2418, #14100a); }
.art-2::before {
  content: ""; position: absolute; inset: 30% 30% 18% 30%;
  border-radius: 40% 40% 8px 8px;
  background: linear-gradient(180deg, #d4b483, #8a6e44);
}
.art-3 { background: linear-gradient(180deg, #1a2438, #0d1320); }
.art-3::before {
  content: ""; position: absolute; inset: 25% 35%;
  background: linear-gradient(180deg, #e0e6f3, #8e96ab);
  border-radius: 4px;
}
.art-4 { background: linear-gradient(180deg, #1f2a26, #0e1614); }
.art-4::before {
  content: ""; position: absolute; inset: 22% 28% 14% 28%;
  background: linear-gradient(180deg, #5dd6a8, #2c8b6a);
  border-radius: 50% 50% 10px 10px;
}
.art-5 { background: linear-gradient(180deg, #2b1f2c, #150d18); }
.art-5::before {
  content: ""; position: absolute; inset: 32% 36% 18% 36%;
  border-radius: 6px;
  background: linear-gradient(180deg, #b88ac7, #6b4a78);
}
.art-6 { background: linear-gradient(180deg, #2a1c1c, #140909); }
.art-6::before {
  content: ""; position: absolute; inset: 30% 30%;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #d97a6b, #6e2c24 70%);
}
.art-7 { background: linear-gradient(180deg, #1c2a2f, #0c1517); }
.art-7::before {
  content: ""; position: absolute; inset: 26% 30% 18% 30%;
  background: linear-gradient(180deg, #84b8c4, #355d68);
  border-radius: 30% 30% 6px 6px;
}
.art-8 { background: linear-gradient(180deg, #2d2a1c, #14130a); }
.art-8::before {
  content: ""; position: absolute; inset: 30% 28%;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 30%, #e6d28a, #7d6a35 70%);
}

.product-art > .swatch {
  position: absolute;
  bottom: 12px; right: 12px;
  display: flex; gap: 6px;
  z-index: 1;
}
.swatch span {
  width: 14px; height: 14px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.2);
  display: inline-block;
}

/* Deals */
.section-deals {
  background:
    radial-gradient(60% 80% at 80% 10%, rgba(212,180,131,0.10), transparent 60%),
    var(--bg-1);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}
.deal-feature {
  grid-row: span 2;
  display: flex;
  flex-direction: column;
}
.deal-card {
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color .2s ease, transform .2s ease;
}
.deal-card:hover { border-color: var(--line-strong); transform: translateY(-2px); }
.deal-art {
  aspect-ratio: 16 / 10;
  position: relative;
  overflow: hidden;
}
.deal-art-feature {
  aspect-ratio: 16 / 11;
  background:
    radial-gradient(60% 60% at 30% 30%, #3b4263, #0f1320 70%);
}
.deal-art-feature::after {
  content: ""; position: absolute; inset: 18% 22%;
  border-radius: 28% 28% 28% 28% / 32% 32% 28% 28%;
  background: radial-gradient(circle at 40% 30%, #5a6188, #1a1d2b 75%);
  box-shadow: inset 0 -20px 40px rgba(0,0,0,0.5), 0 30px 60px rgba(0,0,0,0.5);
}
.deal-art-1 { background: linear-gradient(180deg, #1f2a3e, #0f1420); }
.deal-art-1::after { content: ""; position: absolute; inset: 22% 30% 18% 30%; background: linear-gradient(180deg, #8b94ad, #3a4258); border-radius: 30% 30% 6px 6px; }
.deal-art-2 { background: linear-gradient(180deg, #2a201a, #140e0a); }
.deal-art-2::after { content: ""; position: absolute; inset: 25% 32% 18% 32%; background: linear-gradient(180deg, #cfa97a, #7a5e3e); border-radius: 50% 50% 10px 10px; }
.deal-art-3 { background: linear-gradient(180deg, #2b1c20, #160a0e); }
.deal-art-3::after { content: ""; position: absolute; inset: 28% 36% 16% 36%; background: linear-gradient(180deg, #d97a8a, #6e2c3a); border-radius: 8px; }

.deal-body {
  padding: 18px 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.deal-feature .deal-body { padding: 24px; gap: 12px; flex: 1; }
.deal-feature h3 {
  font-size: 1.6rem;
  line-height: 1.2;
  font-family: "Fraunces", Georgia, serif;
  font-weight: 500;
}
.deal-desc { color: var(--text-muted); margin: 0; }
.badge {
  display: inline-block;
  align-self: flex-start;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--bg-3);
  color: var(--text-muted);
  border: 1px solid var(--line);
}
.badge-accent {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: var(--accent);
}

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}
.article-feature { grid-row: span 2; }
.article-card {
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color .2s ease, transform .2s ease;
  display: flex;
  flex-direction: column;
}
.article-card:hover { border-color: var(--line-strong); }
.article-art {
  position: relative;
  aspect-ratio: 16 / 10;
  background: var(--bg-2);
}
.article-feature .article-art { aspect-ratio: 16 / 11; }
.article-art-1 {
  background:
    radial-gradient(70% 90% at 60% 30%, rgba(212,180,131,0.15), transparent 60%),
    linear-gradient(180deg, #1f2a36, #0c1117);
}
.article-art-1::after {
  content: "";
  position: absolute; inset: 0;
  background:
    linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.5)),
    repeating-linear-gradient(120deg, rgba(255,255,255,0.03) 0 2px, transparent 2px 8px);
}
.article-art-2 { background: linear-gradient(160deg, #2c241a, #100a04); }
.article-art-2::after {
  content: ""; position: absolute; inset: 30% 25%;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 30%, #e0c089, #6e5430 70%);
}
.article-art-3 { background: linear-gradient(160deg, #1a2236, #08101e); }
.article-art-3::after {
  content: ""; position: absolute; inset: 30% 28% 20% 28%;
  background: linear-gradient(180deg, #b6c0d8, #4d5773);
  border-radius: 6px;
}
.article-art-4 { background: linear-gradient(160deg, #1f2a26, #0a1410); }
.article-art-4::after {
  content: ""; position: absolute; inset: 26% 30% 18% 30%;
  background: linear-gradient(180deg, #7eccaa, #2c6f55);
  border-radius: 30% 30% 8px 8px;
}

.article-body {
  padding: 20px 20px 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.article-feature .article-body { padding: 28px; gap: 12px; }
.article-feature h3 {
  font-family: "Fraunces", Georgia, serif;
  font-size: 1.7rem;
  line-height: 1.2;
  font-weight: 500;
}
.article-card h3 a:hover { color: var(--accent); }
.article-meta { color: var(--text-dim); font-size: 0.85rem; margin: 0; }
.tag {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-right: 4px;
}
.byline { color: var(--text-dim); font-size: 0.85rem; margin-top: auto; }
.article-body p:not(.article-meta):not(.byline) { color: var(--text-muted); margin: 0; }

/* Newsletter */
.newsletter {
  border-top: 1px solid var(--line);
  background:
    radial-gradient(50% 80% at 80% 100%, rgba(212,180,131,0.10), transparent 60%),
    var(--bg);
}
.news-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.news-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: center;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 20px;
}
.news-form input[type="email"] {
  background: var(--bg-1);
  border: 1px solid var(--line);
  color: var(--text);
  padding: 14px 16px;
  border-radius: 10px;
  font-size: 1rem;
  width: 100%;
  transition: border-color .15s ease;
}
.news-form input[type="email"]::placeholder { color: var(--text-dim); }
.news-form input[type="email"]:focus-visible {
  border-color: var(--accent);
  outline: 2px solid rgba(212,180,131,0.35);
  outline-offset: 2px;
}
.news-form input[aria-invalid="true"] {
  border-color: var(--danger);
}
.news-form .btn { padding: 14px 22px; }
.news-help, .news-status {
  grid-column: 1 / -1;
  margin: 4px 4px 0;
  font-size: 0.82rem;
  color: var(--text-dim);
}
.news-status { min-height: 1.2em; color: var(--ok); }
.news-status.is-error { color: var(--danger); }

/* Footer */
.site-footer {
  background: var(--bg-1);
  border-top: 1px solid var(--line);
  padding: 64px 0 24px;
  margin-top: 32px;
}
.footer-inner {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 40px;
  border-bottom: 1px solid var(--line);
}
.footer-brand p { color: var(--text-muted); max-width: 36ch; margin: 14px 0 0; }
.site-footer h2 {
  font-family: inherit;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-weight: 600;
  color: var(--text-dim);
  margin: 0 0 14px;
}
.site-footer nav ul {
  list-style: none;
  padding: 0; margin: 0;
  display: grid; gap: 10px;
}
.site-footer nav a { color: var(--text-muted); transition: color .15s ease; }
.site-footer nav a:hover { color: var(--text); }
.footer-bottom {
  padding-top: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  color: var(--text-dim);
  font-size: 0.85rem;
}
.legal { list-style: none; padding: 0; margin: 0; display: flex; gap: 18px; }
.legal a:hover { color: var(--text); }

/* Toast */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--bg-3);
  color: var(--text);
  border: 1px solid var(--line-strong);
  padding: 12px 18px;
  border-radius: 999px;
  box-shadow: var(--shadow-2);
  font-size: 0.92rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s ease, transform .25s ease;
  z-index: 80;
}
.toast.is-visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.001ms !important;
    animation-duration: 0.001ms !important;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .chip, .icon-btn, .news-form input { border: 1px solid CanvasText; }
  .btn-primary { background: Highlight; color: HighlightText; }
  :focus-visible { outline: 2px solid Highlight; }
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-column: span 2; grid-row: auto; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .article-feature { grid-column: span 2; grid-row: auto; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .header-inner { gap: 12px; }
  .primary-nav { display: none; }
  .hero { padding: 40px 0 56px; }
  .hero-inner { grid-template-columns: 1fr; gap: 32px; }
  .hero-art { max-width: 360px; margin: 0 auto; }
  .hero-meta { grid-template-columns: 1fr 1fr; }
  .section { padding: 64px 0; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .article-feature { grid-column: auto; }
  .news-inner { grid-template-columns: 1fr; gap: 24px; }
  .news-form { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr 1fr; gap: 28px; }
}
@media (max-width: 380px) {
  .hero-meta { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
}

