          : "";
      const priceHtml = p.was
        ? `<p class="price"><span class="price-now">${fmt(p.price)}</span><span class="price-was"><s>${fmt(p.was)}</s></span></p>`
        : `<p class="price"><span class="price-now">${fmt(p.price)}</span></p>`;
      const swatchHtml = `<span class="swatch" aria-hidden="true">${p.swatch.map(c => `<span style="background:${c}"></span>`).join("")}</span>`;
