        <li class="product-card">
          <div class="product-art ${p.art}">
            ${tagHtml}
            ${swatchHtml}
          </div>
          <div class="product-body">
            <p class="product-cat">${p.cat}</p>
            <p class="product-name"><a href="#">${p.name}</a></p>
            <div class="product-meta">
              ${priceHtml}
              <button type="button" class="add-mini add-to-cart" data-id="${p.id}" aria-label="Add ${p.name} to cart">
