  font-size: 1.25rem;
  letter-spacing: 0.01em;
}

.primary-nav { flex: 1; }
.primary-nav ul {
  list-style: none;
  display: flex;
  gap: 4px;
  margin: 0; padding: 0;
  justify-content: center;
